extern "C" {
__declspec(dllimport) void __stdcall kailleraShutdown();
__declspec(dllimport) void __stdcall kailleraEndGame();
__declspec(dllimport) int __stdcall kailleraModifyPlayValues(void*,int);
__declspec(dllimport) void __stdcall kailleraInit();
__declspec(dllimport) void __stdcall kailleraSelectServerDialog(void*);
__declspec(dllimport) void __stdcall kailleraSetInfos(void*);
}
int WINAPI WinMain(HINSTANCE h,HINSTANCE p,LPSTR c,int n) {
 GSInitialize(c,c,c); GSConfigure(); GSUpdate();
 kailleraShutdown(); kailleraEndGame(); kailleraModifyPlayValues(c,n);
 kailleraInit(); kailleraSelectServerDialog(0); kailleraSetInfos(0);
 return MessageBoxA(0,c,"Probe",0);
}
